  const getIcon = async (name) => {
    if (!name) return null;
    let clean = name.toLowerCase().trim();
    const bold = clean.endsWith("-bold");
    if (bold) clean = clean.slice(0, -"-bold".length);
    const key = clean.replace(/[_\s]+/g, "-");
    const target = ALIASES[key] || ALIASES[clean] || key;
    const icons = bold ? ICONS_BOLD : ICONS;
    const icon = icons[target] || icons[clean];
    if (icon) {
      return {
        path: icon.path,
        viewBox: icon.viewBox
      };
    }
    return null;
  };

  window.customIconsets["afvalbeheer"] = getIcon;
  window.customIconsets["afval"] = getIcon;

