  const GROFVUIL_LIGHT_BOLD = "";
  const KCA_DARK_BOLD = "";
  const KCA_LIGHT_BOLD = "";
  // END GENERATED BOLD ICONS
  const KCA_LIGHT = "";

  // Returns the perceived brightness (0-255) of a CSS color, or null if it cannot be parsed
  const colorBrightness = (color) => {
    if (!color) return null;
    color = color.trim();
    let r, g, b;
    const hex = color.match(/^#([0-9a-f]{6}|[0-9a-f]{3})/i);
    if (hex) {
      let h = hex[1];
      if (h.length === 3) h = h.split("").map((c) => c + c).join("");
      [r, g, b] = [0, 2, 4].map((i) => parseInt(h.substr(i, 2), 16));
    } else {
      const m = color.match(/^rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)(?:[\s,/]+([\d.]+%?))?/i);
      if (!m) return null;
      if (m[4] !== undefined && parseFloat(m[4]) === 0) return null;
      [r, g, b] = m.slice(1, 4).map(Number);
    }
    return (r * 299 + g * 587 + b * 114) / 1000;
  };

