    kca: { regular: { light: KCA_LIGHT, dark: KCA_DARK }, bold: { light: KCA_LIGHT_BOLD, dark: KCA_DARK_BOLD } },
    restafval: { regular: { light: REST_LIGHT, dark: REST_DARK }, bold: { light: REST_LIGHT_BOLD, dark: REST_DARK_BOLD } },
